pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ParameterizedVault} from "src/ParameterizedVault.sol";
import {Parameters} from "src/Parameters.sol";
import {Treasury} from "src/Treasury.sol";
import {TreasuryFactory} from "src/TreasuryFactory.sol";
import {ImdUSD} from "src/ImdUSD.sol";
import {MockIMD} from "src/MockIMD.sol";
import {ISwarmFeed} from "src/interfaces/ISwarmFeed.sol";
import {APPROVED_OPERATOR, CHAINLINK_ETH_USD, TREASURY_FACTORY} from "src/DeploymentConfig.sol";

contract GasFeed is ISwarmFeed {
    uint256 public constant maxAge = 1 days;
    uint256 private value;
    uint64 private updatedAt;

    constructor(uint256 v) {
        set(v);
    }

    function set(uint256 v) public {
        value = v;
        updatedAt = uint64(block.timestamp);
    }

    function latestValue() external view returns (uint256, uint64) {
        return (value, updatedAt);
    }

    function isStale() external pure returns (bool) {
        return false;
    }
}

contract GasMirror is ISwarmFeed {
    ISwarmFeed private immutable p;

    constructor(ISwarmFeed p_) {
        p = p_;
    }

    function latestValue() external view returns (uint256, uint64) {
        return p.latestValue();
    }

    function isStale() external view returns (bool) {
        return p.isStale();
    }

    function maxAge() external view returns (uint256) {
        return p.maxAge();
    }
}

contract GasAggregator {
    function decimals() external pure returns (uint8) {
        return 8;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}

/// @dev sIMD shape: 24 decimals over an 18-decimal asset; rate = asset raw per 1e18 share raw.
contract GasShare is ERC20 {
    IERC20 public immutable underlying;
    uint256 public constant rate = 7.95e12;

    constructor(IERC20 a) ERC20("sIMD", "sIMD") {
        underlying = a;
    }

    function decimals() public pure override returns (uint8) {
        return 24;
    }

    function asset() external view returns (address) {
        return address(underlying);
    }

    function convertToAssets(uint256 shares) external pure returns (uint256) {
        return shares * rate / 1e18;
    }

    function maxWithdraw(address owner) external view returns (uint256) {
        return balanceOf(owner) * rate / 1e18;
    }

    function withdraw(uint256 assets, address receiver, address owner) external returns (uint256 shares) {
        require(msg.sender == owner, "owner only");
        shares = (assets * 1e18 + rate - 1) / rate;
        _burn(owner, shares);
        underlying.transfer(receiver, assets);
    }

    function deposit(uint256 assets, address receiver) external returns (uint256 shares) {
        underlying.transferFrom(msg.sender, address(this), assets);
        shares = assets * 1e18 / rate;
        _mint(receiver, shares);
    }
}

contract GasToken is ERC20 {
    constructor() ERC20("R", "R") {}

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev A well-formed price source at listing time; once armed, every read spends all the gas it is given.
contract GasBurnFeed {
    uint256 public constant maxAge = 1 days;
    uint256 private immutable price;
    bool public armed;

    constructor(uint256 p) {
        price = p;
    }

    function arm() external {
        armed = true;
    }

    function isStale() external view returns (bool) {
        if (armed) _burn();
        return false;
    }

    function latestValue() external view returns (uint256, uint64) {
        if (armed) _burn();
        return (price, uint64(block.timestamp));
    }

    function _burn() private pure {
        uint256 x;
        while (true) {
            x = x + 1;
        }
    }
}

/// @notice Treasury._boundedCall forwards gas() to a listed price source. A source that answers well at
/// listing and later burns the gas it is given makes every cash (and earn) that reads the reserve cost
/// ~63/64 of the transaction's gas: at an ordinary 3,000,000 gas limit the redemption reverts out of gas,
/// where the same redemption cost ~300,000 gas before the feed turned, for the 48 hours a delisting takes.
contract Proof_BoundedCallGas is Test {
    uint256 private constant IMD_ETH = 0.0005 ether; // $1 at ETH 2000
    address private constant BORROWER = address(0xBA);
    address private constant REDEEMER = address(0xCA);

    MockIMD private imd;
    GasShare private share;
    GasFeed private primary;
    GasFeed private nhi;
    ParameterizedVault private vault;
    Parameters private params;
    Treasury private treasury;
    ImdUSD private stable;

    function setUp() public {
        vm.warp(1_700_000_000);
        vm.roll(20_000_000);
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new GasAggregator()).code);
        imd = new MockIMD();
        share = new GasShare(imd);
        primary = new GasFeed(IMD_ETH);
        nhi = new GasFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(share), address(0), address(0), address(primary), address(nhi), address(new GasMirror(primary))
        );
        params = vault.parameters();
        treasury = vault.treasury();
        stable = vault.stablecoin();
    }

    function _apply() private {
        vm.warp(params.pendingEta());
        primary.set(IMD_ETH);
        nhi.set(0.85 ether);
        vm.prank(address(0xA990));
        params.applyPending();
    }

    function test_aListedFeedThatBurnsGasDoesNotMakeCashUnaffordable() public {
        // A listing the register accepts: well-formed answers, a token with decimals.
        GasToken junk = new GasToken();
        GasBurnFeed feed = new GasBurnFeed(1 ether);
        vm.prank(APPROVED_OPERATOR);
        params.proposeReserveAsset(IERC20(address(junk)), ISwarmFeed(address(feed)), 10_000);
        _apply();
        junk.mint(address(treasury), 100 ether);
        assertEq(treasury.reserveValueUsd(), 100 ether, "listed and counted while healthy");

        // A borrower, some supply in a redeemer's hands, a reserve of sIMD, and a day for the lag.
        vm.prank(APPROVED_OPERATOR);
        imd.mint(BORROWER, 4000 ether);
        vm.startPrank(BORROWER);
        imd.approve(address(vault), 4000 ether);
        vault.lockIMD(4000 ether);
        vault.draw(1000 ether);
        stable.transfer(REDEEMER, 100 ether);
        vm.stopPrank();
        vm.prank(APPROVED_OPERATOR);
        imd.mint(address(this), 100 ether);
        imd.approve(address(share), 100 ether);
        share.deposit(100 ether, address(treasury));
        vm.warp(block.timestamp + 1 days);
        vm.roll(block.number + 1);
        primary.set(IMD_ETH);
        nhi.set(0.85 ether);

        // The feed turns after listing (an upgradeable or externally controlled source).
        feed.arm();

        // EXPECTED (Treasury NatSpec: a dead source "counts for nothing" and "never makes this view revert"):
        // the redemption still costs what it did, about 300,000 gas, so a 3,000,000 limit is ample.
        // ACTUAL on this code: the staticcall forwards gas(), the feed burns 63/64 of it, and cash reverts.
        vm.prank(REDEEMER);
        (bool ok,) = address(vault).call{gas: 3_000_000}(abi.encodeCall(vault.cash, (10 ether, 0, address(0))));
        assertTrue(ok, "cash must not run out of gas because a listed feed burns the gas it is forwarded");
    }
}

