/// @notice Parameters.proposeWorkOracle keys "there is nothing to carry over" on vault.totalEarned() alone.
/// Rights are credited at claim, so an oracle can hold credited, unconsumed rights with nothing minted; a
/// fresh SwarmWorkOracle is then accepted as the successor and those rights are stranded: the old oracle
/// refuses further claims (NotTheVaultsOracle), the vault reads the new one (InsufficientRights).
contract Proof_StrandedRights is Test {
    uint256 private constant IMD_ETH = 0.0005 ether;
    uint256 private constant AGENT = 51450;
    address private constant CONTROLLER = address(0xA11CE);

    MockIMD private imd;
    SrFeed private primary;
    SrFeed private nhi;
    ParameterizedVault private vault;
    Parameters private params;
    SrSeedableWork private work;

    function setUp() public {
        vm.warp(1_700_000_000);
        vm.roll(20_000_000);
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(WORK_ORACLE_FACTORY, address(new SrSeedableWorkFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new SrAggregator()).code);
        imd = new MockIMD();
        SrShare share = new SrShare(imd);
        primary = new SrFeed(IMD_ETH);
        nhi = new SrFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(share), address(0), WORK_ORACLE_SENTINEL, address(primary), address(nhi), address(new SrMirror(primary))
        );
        params = vault.parameters();
        work = SrSeedableWork(address(vault.oracle()));
    }

    function _apply() private {
        vm.warp(params.pendingEta());
        primary.set(IMD_ETH);
        nhi.set(0.85 ether);
        vm.prank(address(0xA990));
        params.applyPending();
    }

    function _setWage(uint256 wad) private {
        vm.prank(APPROVED_OPERATOR);
        params.proposeWage(wad);
        _apply();
    }

    /// @dev A two-leaf StandardMerkleTree holding the agent's leaf and one other.
    function _tree(uint256 id, uint32 accepted, uint64 cumulative) private pure returns (bytes32 root, bytes32[] memory proof) {
        bytes32 a = keccak256(bytes.concat(keccak256(abi.encode(id, accepted, cumulative))));
        bytes32 b = keccak256(bytes.concat(keccak256(abi.encode(uint256(1), uint32(1), uint64(1)))));
        root = a < b ? keccak256(abi.encodePacked(a, b)) : keccak256(abi.encodePacked(b, a));
        proof = new bytes32[](1);
        proof[0] = b;
    }

    function test_aReplacementIsRefusedWhileTheCurrentOracleHoldsCreditedUnconsumedRights() public {
        // Before any claim a fresh successor is a valid proposal (nothing to carry over), and is cancelled.
        SwarmWorkOracle early = new SwarmWorkOracle(address(vault), 1 days);
        vm.prank(APPROVED_OPERATOR);
        params.proposeWorkOracle(address(early));
        vm.prank(APPROVED_OPERATOR);
        params.cancel();

        // Governance turns the wage on; an agent's controller claims 500 attested tasks and mints nothing.
        _setWage(1 ether);
        (bytes32 root, bytes32[] memory proof) = _tree(AGENT, 500, 500);
        work.seed(uint256(root));
        work.recordRoot();
        vm.mockCall(
            ERC8004_ADAPTER, abi.encodeWithSignature("isController(uint256,address)", AGENT, CONTROLLER), abi.encode(true)
        );
        vm.prank(CONTROLLER);
        assertEq(work.claim(AGENT, 500, 500, proof, root), 500 ether);
        assertEq(work.mintingRights(CONTROLLER), 500 ether, "credited, unconsumed");
        assertEq(vault.totalEarned(), 0, "nothing minted");

        // Governance turns the wage off, as proposeWorkOracle requires, and proposes a fresh SwarmWorkOracle.
        _setWage(0);
        SwarmWorkOracle successor = new SwarmWorkOracle(address(vault), 1 days);
        // EXPECTED: refused, because the current oracle still carries credited rights the successor cannot
        // carry over (the same rule that applies once anything has been minted).
        // ACTUAL on this code: accepted; applied 48 hours later the 500e18 rights are stranded in the old
        // oracle (it refuses claims once superseded; the vault reads the successor, which holds nothing).
        vm.prank(APPROVED_OPERATOR);
        vm.expectRevert();
        params.proposeWorkOracle(address(successor));
    }
}

