/// @dev A listed price source that answers well-formed words at listing and later burns every unit of gas
/// it is forwarded (an upgradeable or hostile feed after a 48-hour listing).
contract GasBurningFeed is ISwarmFeed {
    bool public burn;
    uint256 public constant maxAge = 1 days;

    function setBurn(bool on) external {
        burn = on;
    }

    function isStale() external view returns (bool) {
        if (burn) {
            assembly {
                invalid()
            }
        }
        return false;
    }

    function latestValue() external view returns (uint256, uint64) {
        return (1e18, uint64(block.timestamp));
    }
}

contract OffsetFeed is ISwarmFeed {
    uint256 private immutable v;
    uint256 public constant maxAge = 1 days;

    constructor(uint256 v_) {
        v = v_;
    }

    function isStale() external pure returns (bool) {
        return false;
    }

    function latestValue() external view returns (uint256, uint64) {
        return (v, uint64(block.timestamp));
    }
}

contract Mirror is ISwarmFeed {
    ISwarmFeed private immutable src;

    constructor(ISwarmFeed s) {
        src = s;
    }

    function isStale() external view returns (bool) {
        return src.isStale();
    }

    function latestValue() external view returns (uint256, uint64) {
        return src.latestValue();
    }

    function maxAge() external view returns (uint256) {
        return src.maxAge();
    }
}

