}

/// @notice Treasury._boundedCall bounds the returndata copy but forwards all gas (`gas()`), so a listed
/// source that burns what it is forwarded makes every reader of reserveValueUsd pay the whole
/// transaction's gas, and with three such listings the sum reverts at the block gas limit.
contract ReserveReadGasTest is Test {
    MockIMD private imd;
    ParameterizedVault private vault;
    Treasury private treasury;
    Parameters private params;
    GasBurningFeed private feed;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new Agg()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        OffsetFeed primary = new OffsetFeed(0.0005 ether); // $1 per IMD at $2000/ETH
        OffsetFeed nhi = new OffsetFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(nhi), address(new Mirror(primary))
        );
        treasury = vault.treasury();
        params = vault.parameters();
        feed = new GasBurningFeed();
    }

    /// @dev Lists `n` distinct tokens, each holding 100 units at the Treasury, against the same feed, each
    /// through the real 48-hour proposal.
    function _list(uint256 n) private {
        for (uint256 i; i < n; ++i) {
            Rsv rsv = new Rsv();
            rsv.mint(address(treasury), 100e18);
            vm.prank(APPROVED_OPERATOR);
            params.proposeReserveAsset(IERC20(address(rsv)), feed, 10_000);
            vm.warp(params.pendingEta());
            params.applyPending();
        }
        assertEq(treasury.reserveValueUsd(), n * 100e18, "listed and valued while the feed behaves");
    }

    function test_oneBurningFeedMakesEveryReadCostTheWholeTransaction() public {
        _list(1);
        feed.setBurn(true);
        uint256 before = gasleft();
        (bool ok,) = address(treasury).staticcall{gas: 5_000_000}(abi.encodeCall(treasury.reserveValueUsd, ()));
        uint256 used = before - gasleft();
        assertTrue(ok, "one burning source: the sum survives on the 1/64 it keeps");
        // EXPECTED: a source that counts for nothing costs about one external call. ACTUAL: the whole 5M
        // forwarded is burned; the same happens inside every earn, cash and backingPerUnit.
        assertLt(used, 1_000_000, "a read must not cost the whole transaction's gas");
    }

    function test_threeBurningListingsRevertTheSumAtTheBlockGasLimit() public {
        _list(3);
        feed.setBurn(true);
        // EXPECTED (Treasury.reserveValueUsd NatSpec, lines 206-208: 'it never makes this view revert'):
        // the three assets count for nothing and the view completes. ACTUAL: each read keeps 1/64 of what
        // it had, (1/64)^3 of 30M is about 114 gas, and the sum runs out of gas.
        (bool ok,) = address(treasury).staticcall{gas: 30_000_000}(abi.encodeCall(treasury.reserveValueUsd, ()));
        assertTrue(ok, "reserveValueUsd must not revert because of listed sources");
    }
}
